# Generated artifacts: PR specs, derived 1:1 from data_issues.ISSUES so every
# PR links a real issue id and a matching title. Regenerated by the renderer.

from __future__ import annotations

import hashlib

from data_issues import ISSUES

# Deterministic pseudo-shas so the backlog is regenerable and diff-stable.
def _sha(seed: str) -> str:
    return hashlib.sha1(seed.encode("utf-8")).hexdigest()[:7]


def _slug(text: str) -> str:
    out = []
    for ch in text.lower():
        if ch.isalnum():
            out.append(ch)
        elif ch in " -_":
            out.append("-")
    slug = "".join(out)
    while "--" in slug:
        slug = slug.replace("--", "-")
    slug = slug.strip("-")
    if len(slug) > 48:
        slug = slug[:48].rsplit("-", 1)[0].strip("-")
    return slug


# Label -> (crate path, module) for realistic file lists.
_PATH_MAP = [
    (("capture",), "crates/curbcut-capture/src", "adapter"),
    (("a11y",), "crates/curbcut-a11y/src", "adapter"),
    (("vision",), "crates/curbcut-vision/src", "model"),
    (("understand",), "crates/curbcut-comprehension/src", "engine"),
    (("adapt",), "crates/curbcut-adapt/src", "engine"),
    (("tts",), "crates/curbcut-tts/src", "synth"),
    (("input",), "crates/curbcut-input/src", "router"),
    (("render",), "apps/ui/src/lib", "View"),
    (("frontend",), "apps/ui/src/lib", "Panel"),
    (("store",), "crates/curbcut-core/src/store", "schema"),
    (("privacy",), "crates/curbcut-core/src/privacy", "guard"),
    (("security",), "crates/curbcut-core/src/security", "guard"),
    (("core",), "crates/curbcut-core/src", "bus"),
    (("platform",), "crates/curbcut-core/src/platform", "os"),
    (("ci",), ".github/workflows", "ci.yml"),
    (("testing",), "tests", "regression"),
    (("release",), "packaging", "manifest"),
    (("docs",), "docs", "guide"),
    (("legal",), "docs/legal", "agreement"),
    (("community",), "docs", "community"),
    (("ethics",), "docs", "ethics"),
    (("models",), "crates/curbcut-models/src", "manifest"),
    (("perf",), "crates/curbcut-perf/src", "budget"),
    (("i18n",), "crates/curbcut-i18n/src", "locale"),
    (("llm",), "crates/curbcut-comprehension/src/llm", "client"),
    (("extension",), "apps/extension/src", "background"),
    (("web",), "apps/extension/src", "content"),
]

_TYPE_PREFIX = {
    "feat": "feat",
    "fix": "fix",
    "chore": "chore",
    "docs": "docs",
    "test": "test",
    "perf": "perf",
    "refactor": "refactor",
}


def _ext(base: str) -> str:
    if base.startswith("apps/"):
        return ".svelte"
    if base.startswith(".github/"):
        return ".yml"
    if base.startswith("docs"):
        return ".md"
    if base.startswith("packaging"):
        return ".sh"
    return ".rs"


def _files_for(issue: dict) -> list[str]:
    labels = set(issue["labels"])
    paths: list[str] = []
    for keys, base, leaf in _PATH_MAP:
        if labels & set(keys):
            paths.append("%s/%s%s" % (base, leaf, _ext(base)))
    if issue["type"] == "docs":
        paths = ["docs/%s.md" % _slug(issue["title"])]
    if not paths:
        paths = ["crates/curbcut-core/src/%s.rs" % _slug(issue["title"])]
    # Keep it to a realistic 2-4 files.
    paths = paths[:3]
    if issue["type"] in ("feat", "fix", "refactor", "perf"):
        paths.append("crates/curbcut-core/tests/%s.rs" % _slug(issue["title"]))
    elif issue["type"] == "test":
        paths = ["tests/%s.rs" % _slug(issue["title"]), "tests/fixtures/README.md"]
    return paths


def _commits_for(issue: dict) -> list[str]:
    first = _sha(issue["id"] + ":c1")
    if issue["type"] in ("feat", "perf", "refactor") and issue["size"] in ("L", "M"):
        return [first, _sha(issue["id"] + ":c2")]
    return [first]


def _reviews_for(issue: dict) -> list[tuple[str, str]]:
    labels = set(issue["labels"])
    pool = ["code-reviewer"]
    if labels & {"security", "privacy"}:
        pool.append("security-reviewer")
    if labels & {"testing", "perf"}:
        pool.append("test-reviewer")
    if labels & {"vision", "models", "llm"}:
        pool.append("ml-reviewer")
    if labels & {"frontend", "render", "adapt", "a11y"}:
        pool.append("design-reviewer")
    if labels & {"release", "legal", "docs"}:
        pool.append("docs-reviewer")
    if labels & {"store", "privacy"}:
        pool.append("database-reviewer")

    verdict = "APPROVE"
    comment = None
    if issue["priority"] == "P0":
        comment = "COMMENT: add a regression test for the failure mode"
    elif labels & {"security", "privacy"}:
        comment = "COMMENT: confirm the no-content-logging assertion"
    elif labels & {"vision", "models"}:
        comment = "COMMENT: attach the benchmark delta"
    elif labels & {"a11y", "render", "input"}:
        comment = "COMMENT: verify keyboard path manually"

    reviews = [(pool[0], verdict)]
    if comment:
        reviews.insert(0, (pool[-1], comment))
    if len(pool) > 2:
        reviews.append((pool[1], "APPROVE"))
    return reviews[:3]


def _build() -> list[dict]:
    prs = []
    for idx, issue in enumerate(ISSUES, start=1):
        pr_id = "PR-%03d" % idx
        prefix = _TYPE_PREFIX.get(issue["type"], "chore")
        branch = "%s/%s" % (prefix, _slug(issue["title"]))
        commits = _commits_for(issue)
        prs.append(
            dict(
                id=pr_id,
                title="%s: %s" % (prefix, issue["title"]),
                branch=branch,
                issues=[issue["id"]],
                commits=commits,
                files=_files_for(issue),
                ci="pass",
                reviews=_reviews_for(issue),
                merged=True,
            )
        )
    return prs


PRS = _build()
